"""
csv_sales_aggregate.py

Aggregate sales data from CSV text, grouping by (region, product)
and summing quantity and cents.
"""

import csv
import io
from collections import defaultdict

REQUIRED_FIELDS = {"region", "product", "quantity", "cents"}


def _parse_row(row: dict) -> tuple[str, str, int, int] | None:
    """
    Validate and extract fields from a CSV row dict.
    Returns (region, product, quantity, cents) or None if the row is malformed.
    """
    if not isinstance(row, dict):
        return None

    if not REQUIRED_FIELDS.issubset(row.keys()):
        return None

    region = row["region"].strip() if isinstance(row["region"], str) else ""
    product = row["product"].strip() if isinstance(row["product"], str) else ""

    if not region or not product:
        return None

    try:
        quantity = int(row["quantity"])
        cents = int(row["cents"])
    except (ValueError, TypeError):
        return None

    return region, product, quantity, cents


def _accumulate_rows(reader: csv.DictReader) -> dict[tuple[str, str], dict[str, int]]:
    """
    Iterate over CSV rows, parse each one, and accumulate quantity/cents totals
    keyed by (region, product).
    """
    if not isinstance(reader, csv.DictReader):
        raise TypeError(f"Expected csv.DictReader, got {type(reader).__name__}")

    totals: dict[tuple[str, str], dict[str, int]] = defaultdict(
        lambda: {"quantity": 0, "cents": 0}
    )
    for row in reader:
        parsed = _parse_row(row)
        if parsed is None:
            continue
        region, product, quantity, cents = parsed
        totals[(region, product)]["quantity"] += quantity
        totals[(region, product)]["cents"] += cents
    return totals


def _build_result(
    totals: dict[tuple[str, str], dict[str, int]], min_quantity: int
) -> list[dict]:
    """
    Convert accumulated totals into the final sorted list of dicts,
    filtering out groups below min_quantity.
    """
    if not isinstance(totals, dict):
        raise TypeError(f"Expected dict for totals, got {type(totals).__name__}")
    if not isinstance(min_quantity, int):
        raise TypeError(
            f"Expected int for min_quantity, got {type(min_quantity).__name__}"
        )

    return [
        {"region": region, "product": product, **sums}
        for (region, product), sums in sorted(totals.items())
        if sums["quantity"] >= min_quantity
    ]


def aggregate_sales(csv_text: str, *, min_quantity: int = 0) -> list[dict]:
    """
    Parse CSV text and return aggregated sales grouped by (region, product).

    Skips rows with missing/malformed fields or non-integer quantity/cents.
    Returns a list of dicts sorted by region then product, each containing:
        {"region": str, "product": str, "quantity": int, "cents": int}

    Args:
        csv_text: Raw CSV string with headers region, product, quantity, cents.
        min_quantity: Exclude groups whose total quantity is less than this value.

    Raises:
        TypeError: If csv_text is not a str or min_quantity is not an int.
        ValueError: If min_quantity is negative.
    """
    if not isinstance(csv_text, str):
        raise TypeError(
            f"csv_text must be a str, got {type(csv_text).__name__}"
        )
    if not isinstance(min_quantity, int):
        raise TypeError(
            f"min_quantity must be an int, got {type(min_quantity).__name__}"
        )
    if min_quantity < 0:
        raise ValueError(
            f"min_quantity must be non-negative, got {min_quantity}"
        )

    reader = csv.DictReader(io.StringIO(csv_text))
    totals = _accumulate_rows(reader)
    return _build_result(totals, min_quantity)

